import math

def is_square(k):
    if k < 0:
        return False
    root = int(math.isqrt(k))
    return root * root == k

def check_cool(n):
    """
    Checks if n is a cool integer using backtracking.
    n is cool if there exists a permutation (x1, ..., xn) of (1, ..., n)
    such that no prefix sum is a perfect square.
    """
    if n == 0:
        return True

    available = set(range(1, n + 1))

    def solve(current_sum, used_mask, length):
        if length == n:
            # We successfully placed all n elements
            return True

        for x in range(1, n + 1):
            if not (used_mask & (1 << (x - 1))):
                new_sum = current_sum + x
                if not is_square(new_sum):
                    new_mask = used_mask | (1 << (x - 1))
                    if solve(new_sum, new_mask, length + 1):
                        return True
        return False

    # Start search from sum 0, no elements used, length 0
    return solve(0, 0, 0)

