import math
import itertools

def is_perfect_square(k):
    if k < 0:
        return False
    if k == 0:
        return True
    sqrt_k = int(math.isqrt(k))
    return sqrt_k * sqrt_k == k

def is_cool(n):
    """
    Uses backtracking to check if there exists a permutation of (1..n) 
    such that no prefix sum is a perfect square.
    """
    if is_perfect_square(n * (n + 1) // 2):
        # Optimization: If total sum is a square, it's not cool.
        return False

    available = set(range(1, n + 1))

    def solve(current_sum, permutation_length):
        if permutation_length == n:
            return True

        # Try every available number
        for x in sorted(list(available)): # Sorting ensures consistent order, though not strictly required
            next_sum = current_sum + x

            if not is_perfect_square(next_sum):
                # Choose x
                available.remove(x)

                # Recurse
                if solve(next_sum, permutation_length + 1):
                    # Found a valid path
                    available.add(x) # Backtrack setup
                    return True

                # Backtrack
                available.add(x)

        return False

    return solve(0, 0)

# Test range: n=23 up to n=60
start_n = 23
end_n = 60

results = {}
for n in range(start_n, end_n + 1):
    # Only test candidates where S_n is NOT a perfect square, as per the prompt's focus.
    # We know n=49 has S_49 = 35^2, so we skip it based on the prompt's spirit, 
    # but the internal is_cool check also handles this.

    if not is_perfect_square(n * (n + 1) // 2):
        try:
            cool = is_cool(n)
            results[n] = cool
        except RecursionError:
            results[n] = "Timeout/Recursion Limit"

print("--- Coolness Test Results (n=23 to n=60) ---")
for n, is_c in sorted(results.items()):
    print(f"n={n}: Cool = {is_c}")
